        assertThat(erroDe(new ResumoRequest(List.of(), "XPTO", "XPTO", "XPTO", 99, "XPTO", "XPTO")))
                .isEqualTo(ErroCheckout.PEDIDO_INVALIDO);
        assertThat(erroDe(new ResumoRequest(List.of(item("Camiseta", "79.90", 0, "0.30")), "EXPRESSA",
